@code {
    private TmSpreadsheet _spreadsheet = null!;

    private void SetupData()
    {
        var sheet = _spreadsheet.Workbook.ActiveSheet;
        sheet.SetCellValue(0, 0, "Revenue");
        sheet.SetCellValue(0, 1, "Expenses");
        sheet.SetCellValue(0, 2, "Profit");
        sheet.SetCellValue(1, 0, 100000);
        sheet.SetCellValue(1, 1, 75000);
        sheet.SetCellValue(1, 2, "=A2-B2");
    }

    private async Task DownloadAsync()
    {
        var data = await _spreadsheet.ExportToExcelAsync();
        // download data...
    }
}

