<TmSpreadsheet @ref="_sheet"
               RowsCount="50"
               ColumnsCount="15" />

@code {
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            var s = _sheet.Workbook.ActiveSheet;
            s.SetCellValue(0, 0, "Sales");
            s.SetCellValue(0, 1, "Target");
            s.SetCellValue(0, 2, "Achievement %");
            s.SetCellValue(1, 0, 85000);
            s.SetCellValue(1, 1, 100000);
            s.SetCellValue(1, 2, "=A2/B2*100");
            s.SetCellValue(2, 0, "=SUM(A2:A10)");
            s.SetCellValue(2, 1, "=AVERAGE(B2:B10)");
        }
    }
}
